-- 0068_clause_polish_v4.sql
-- 条款库 v4 全量打磨（owner 07-23：默认条款开箱即用覆盖95%）：
-- 参数占位符烘焙为行业默认值（计量25日/次月15日付/验收7日/签证14+7日/逾期日万分之五/质保金3%缺陷期12个月等），
-- 仅保留主体/金额/日期/工程信息类核心占位符；全部95行经规则层自检零命中。
-- 素材：四个条款打磨 agent 产出 + docs/superpowers/specs/2026-07-22-contract-sample-findings.md

UPDATE contract_clause_template SET title = '首部与签约依据', body_template = '甲方（发包方）：{{party_a}}
统一社会信用代码：{{party_a_credit_code}}
住所地：{{party_a_address}}
法定代表人：{{party_a_legal_person}}

乙方（承包方）：{{party_b}}
统一社会信用代码：{{party_b_credit_code}}
住所地：{{party_b_address}}
法定代表人：{{party_b_legal_person}}

根据《中华人民共和国民法典》《中华人民共和国建筑法》《中华人民共和国安全生产法》及相关法律法规，甲乙双方在平等、自愿、协商一致的基础上，就{{project_name}}顶管施工事宜订立本协议，共同信守履行。涉及营业线铁路、轨道交通、高速公路等特殊区域施工的，双方同时遵守相关管理单位的施工安全管理规定。', risk_notes = '法律引用仅限现行有效法律（严禁已废止《合同法》）；首部住所地与送达条款联动，务必填写可实际收件地址。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'parties_basis' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '工程概况', body_template = '（一）工程名称：{{project_name}}。（二）工程地点：{{location}}。（三）施工内容：{{pipe_spec}}管道土压平衡顶进施工，顶进长度约{{length}}米，包含顶管设备安装调试、管节顶进、注浆减阻、管内出土及贯通测量等全部顶进作业，完工后按双方现场签认的实际贯通长度据实结算。（四）施工工艺与技术要求：严格按施工图纸、地勘报告及经批准的施工方案执行；顶进过程中管道中心线与高程偏差应符合《给水排水管道工程施工及验收规范》（GB 50268）的允许偏差要求，超限应及时纠偏并如实记录。', risk_notes = '顶管参数（管径×节长×壁厚、顶进长度、工艺）必须写实，禁止“按实际情况”类含糊表述；锚定现行国标GB 50268增强验收确定性。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'project_overview' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '工程量与计价', body_template = '本工程综合单价为人民币{{unit_price}}元/米（含税），顶进长度约{{length}}米，暂定总价人民币{{amount}}元（大写：{{amount_cn}}）。上述价款为增值税含税价，适用税率{{tax_rate}}%，不含税金额与税额按法定口径分列，以乙方开具的合规增值税发票载明金额为准；国家调整增值税税率的，双方按调整后税率签订补充协议相应调整含税价款。综合单价已包含完成本协议施工内容所需的人工、设备使用及摊销、减阻材料、管理费、利润、税金与一般风险费用；最终结算价＝双方现场签认的实际贯通长度×综合单价，除双方书面签认的变更外，综合单价包干使用，不因市场物价波动调整。', risk_notes = '大写金额由系统后端生成填入{{amount_cn}}，AI不得自行推算；包干范围逐项列明压缩“是否包干”争议；保留税率调整机制。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'quantity_pricing' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '工程期限与顺延', body_template = '计划开工日期：{{start_date}}；计划竣工日期：{{end_date}}。有下列情形之一的，工期相应顺延：（一）甲方未按约提供工作坑、管材、水电、图纸资料等施工条件的；（二）发生设计变更或工程量增加的；（三）遭遇不可抗力或异常恶劣天气的；（四）发生非乙方原因的停水停电、政府或铁路等管理单位指令性停工的。顺延天数以双方签认的工程联系单为准；乙方应于顺延事由发生后7日内书面提出，双方应于收到后7日内完成签认或书面提出异议，顺延签证不得以口头形式作出。', risk_notes = '竣工日期不得早于开工日期（校验规则拦截倒挂笔误）；顺延事由清单化＋7日双向签认程序，防“口头同意顺延”举证不能。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'duration' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '发票与税务', body_template = '乙方应向甲方开具税率为{{tax_rate}}%的增值税专用发票，发票品目与本协议施工内容（建筑服务）一致，备注栏注明建筑服务发生地及工程项目名称。发票仅向本协议甲方开具，甲方付款仅支付至本协议落款载明的乙方对公账户，做到合同流、发票流、资金流三流一致。乙方应于每期收款前开具并送达对应金额的合规发票；发票不合规的，甲方有权要求换开，换开期间相应付款期限顺延，但甲方不得以发票轻微形式瑕疵为由拒付经签认的工程款。', risk_notes = '三流一致硬约束：严禁向第三方开票、严禁品目错配（如以机械租赁品目开建筑服务）；先票后款＋换开顺延为均衡设置。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'invoice_tax' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '文明施工', body_template = '乙方应按甲方现场整体规划组织文明施工：作业区域设置必要的围挡与警示标志，作业垃圾及废弃泥浆集中收集后运至甲方指定地点，做到工完料净场地清；加强施工现场及生活区管理，不得违章作业、野蛮施工，不得扰民滋事。泥浆外运应采取密闭防漏措施并遵守当地渣土、排污管理规定，因乙方违规排放受到的处罚由乙方承担；因甲方指定弃置地点违规导致的处罚由甲方承担。甲方应为文明施工提供必要的场地、水电及材料堆放条件。', risk_notes = '顶管泥浆外运是文明施工执法高频点；排放责任按行为与指令归属划分，双向均衡。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'civilized_construction' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '不可抗力与工期顺延', body_template = '因不可抗力致使本协议部分或全部不能履行的，根据影响程度部分或全部免除责任，但法律另有规定的除外。遭遇不可抗力的一方应于不可抗力发生后7日内书面通知对方，并在合理期限内提供有关部门出具的证明材料；迟延通知致使损失扩大的，就扩大部分不予免责。不可抗力期间的损失按下列规则分担：已完工程量由甲方按本协议单价据实结算；双方人员伤亡及设备、财产损失由双方各自承担；停工期间必要的现场看护费用由甲方承担；工期相应顺延，顺延天数以双方签认为准。', risk_notes = '分担规则按施工合同示范文本口径（看护费归发包方、各自损失各担）；历史范本均缺失本节，属遗漏补齐。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'force_majeure' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '成品保护与移交', body_template = '管道贯通并经检验合格后，乙方应向甲方办理书面移交手续，双方签署移交单；自移交单签署之日起，成品保护责任及毁损灭失风险转移由甲方承担。移交前因乙方施工或保管不善造成的成品损坏，由乙方负责修复并承担费用；移交前因甲方或第三方原因造成的损坏，由责任方承担修复费用，乙方应予配合并据实签认。甲方无正当理由拒绝或拖延办理移交手续的，自乙方书面提请移交之日起满7日视为已完成移交，成品保护责任相应转移。', risk_notes = '“拖延办理视为移交”防以不办手续无限延长乙方保管责任；风险随移交单转移，界限清晰。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'handover_protection' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '保险', body_template = '乙方应为其全部进场施工人员投保工伤保险或建筑施工人员团体意外伤害保险并承担保费，保险凭证留存甲方备查；应保未保期间发生人身伤害的，相应赔偿责任由乙方承担，但依法应由其他责任方承担的部分除外。本工程已由建设单位或上游总承包合同统一投保工程一切险及第三者责任险的，从其保险安排；未统一投保的，是否另行投保由甲方决定并承担相应保费。发生保险事故时，双方应互相配合完成报案、查勘与理赔手续，理赔所得按损失归属分配。', risk_notes = '人员保险硬性归乙方（用工合规底线）；工程一切险默认从上游安排，避免重复投保与费用争议。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'insurance' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '争议解决', body_template = '因本协议及其补充协议发生的或与之相关的任何争议，双方应首先友好协商解决；协商不成的，任何一方均有权向原告住所地人民法院提起诉讼。争议处理期间，除争议部分外，双方应继续履行本协议的无争议部分；已完工程量的计量签认及已到期无争议款项的支付，不受争议影响。因追索欠款或索赔发生的合理维权费用（含诉讼费、保全费、公证费及合理律师费），由败诉方或责任方承担。', risk_notes = '“原告住所地”系民诉法允许的协议管辖点，对等且我方主张权利时即为我方主场；outbound强势场景可改“甲方所在地”，inbound可争取“乙方所在地”。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'dispute' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '其他与生效', body_template = '本协议自双方盖章并经法定代表人或授权代理人签字之日起生效，生效不以任何一方缴纳保证金或办理其他手续为前提。未尽事宜双方另行签订书面补充协议，补充协议与本协议具有同等效力；两者不一致的，以在后签订者为准。本协议一式四份，甲方执二份，乙方执二份，各份具有同等法律效力，扫描件、传真件与原件具有同等效力。本协议任何空白栏目应在用印前填写完整或划线注销，留白视为对相应事项未作约定；协议内容手写涂改未经双方盖章确认的无效。', risk_notes = '“留白视为未约定”＋用印前填写完整源自生产样本教训（已盖章合同7处条款留白）；生效不附加保证金前提，防内部矛盾。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'misc_effective' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '落款', body_template = '甲方（盖章）：{{party_a}}
法定代表人/委托代理人：{{party_a_legal_person}}
地址：{{party_a_address}}
统一社会信用代码：{{party_a_credit_code}}
开户银行：{{party_a_bank_name}}
账号：{{party_a_bank_account}}
联系电话：{{party_a_phone}}
签约日期：{{sign_date}}

乙方（盖章）：{{party_b}}
法定代表人/委托代理人：{{party_b_legal_person}}
地址：{{party_b_address}}
统一社会信用代码：{{party_b_credit_code}}
开户银行：{{party_b_bank_name}}
账号：{{party_b_bank_account}}
联系电话：{{party_b_phone}}
签约日期：{{sign_date}}', risk_notes = '个人证件号码一律不进正文；付款仅入落款载明对公账户，账户变更须加盖公章书面通知。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'signature_block' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '送达条款', body_template = '双方确认本协议首部及落款载明的地址为有效送达地址，适用于履约过程中的通知、函件、签证索赔资料等非诉文书的送达，以及争议解决阶段（含仲裁、一审、二审、再审与执行程序）司法文书的送达。一方变更送达地址的，应于变更后7日内书面通知对方；未依约通知的，原地址仍视为有效送达地址，由此产生的送达不能风险由变更方承担。以邮寄方式送达的，交邮后第三日视为送达；直接送交的，签收之日视为送达；受送达方拒收或无人签收的，文书退回之日视为送达。', risk_notes = '覆盖诉讼全阶段的地址确认条款，防“查无此人/拒收”送达僵局；绝大多数中小合同缺失本节。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'service_notice' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '变更管理', body_template = '（一）非因乙方原因发生的设计变更、工程量增减或施工条件重大变化，乙方按签证与索赔条款程序报送，价款与工期据实调整；变更内容能套用本协议综合单价的按协议单价执行，无适用单价的由双方参照签约时市场价格水平协商签认。（二）因乙方原因造成的变更、返工，费用由乙方自行承担，工期不予顺延。（三）变更减少工程量的，减少部分按协议单价核减；乙方为该部分已实际发生的合理投入（含已进场专用材料、已完成的措施性工作），经双方签认后据实补偿。（四）任何变更均应形成书面签证后实施；紧急情形下可先实施，但应于实施后7日内补办签证手续。', risk_notes = '三分归责（非承包人原因／承包人原因／核减）＋定价顺位（协议单价→市场价协商）；“先实施后补签”限紧急情形。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'change_management' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '承包方式与工作界面', body_template = '本工程采用包工包设备（顶进作业）方式承包。甲方负责提供：施工手续及许可、施工图纸、地勘报告、地下管线物探资料、安全与技术交底、顶进工作坑及接收坑（含后背墙、安全爬梯、坑内照明、防护及防排水措施，后背墙强度应满足最大顶力要求）、经检验合格的管材及接口配件并卸管至工作坑吊装范围、施工用水用电接至坑边、管内出土的地面外弃、进出场道路畅通及设备停放场地。乙方负责提供：顶管主机及辅助顶进设备、起重设备、施工作业人员、减阻注浆材料，并完成管道内土方水平运输至工作坑地面。双方工作界面及施工条件交接以书面签认为准；甲方所供条件不符合约定标准的，视为未提供，乙方有权按停窝工补偿及工期顺延条款主张权利。', risk_notes = 'inbound甲供清单越细越有利：“后背墙满足最大顶力”“合格管材卸至吊装范围”等验收口径写实；甲供不达标视为未提供，直接衔接停窝工条款。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'scope_interface' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '工程质量与验收', body_template = '工程质量标准：合格，按国家现行施工及验收规范（含GB 50268）执行。乙方施工中应如实填写顶进记录（顶程、中心线偏差、高程偏差、注浆量），甲方及监理有权随时查阅。管道全线贯通后，乙方书面提请验收，甲方应在收到验收申请后7日内组织竣工验收并出具书面验收意见；甲方逾期不组织验收或不出具意见的，视为本工程质量合格，自乙方提请验收之日起满7日即为验收合格之日。验收中发现的质量问题属乙方施工原因的，乙方限期无偿整改，整改合格之日为验收合格之日；属管材本身缺陷或甲供条件原因的，处理责任与费用由甲方承担，工期相应顺延。', risk_notes = '“逾期不验收视为合格”是乙方核心保护条款，保留；质量问题按成因分责，防管材缺陷向乙方转嫁。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'quality_acceptance' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '价款结算与支付', body_template = '（一）启动款：顶管设备安装调试完毕并经双方确认具备顶进条件后7日内，甲方向乙方支付启动款，金额为暂定总价的20%，启动款在各期进度款及结算款中依次抵扣，最迟于结算时抵扣完毕。（二）进度款：施工期间每月25日双方共同计量当月完成工程量并书面签认，甲方于次月15日前支付当月经签认工程量金额的60%。（三）结算款：竣工验收合格后30日内双方完成结算，甲方于结算完成后7日内将累计付款付至结算总价的97%。（四）质量保证金：预留结算总价的3%，缺陷责任期12个月，期满且无未处理质量问题的，甲方于期满后15日内无息退还。甲方的各项付款义务均独立存在，不以甲方收到任何第三方（含建设单位）款项为前提；无论双方是否另有付款联动安排，甲方最迟应于对应工程量计量签认后60日内付清该期款项。甲方逾期付款的，每逾期一日按未付金额的万分之五向乙方支付违约金；逾期超过30日的，乙方有权暂停施工，由此增加的费用与工期由甲方承担。', risk_notes = '付款节点全部为确定期限；“第三方付款不作为前提＋签认后60日兜底”是反转嫁核心；日万分之五＋暂停施工权双重防线。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'payment' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '安全施工', body_template = '（一）甲方不得要求乙方违反安全管理规定施工；因甲方提供的资料失实、场地及设施缺陷或甲方违章指令导致的安全事故，由甲方承担相应责任及费用。（二）乙方应遵守工程建设安全生产管理规定，按安全标准组织施工：落实进场安全教育、分部分项安全技术交底、特种作业人员持证上岗、坑下作业通风与临时用电防护等措施，如实记录并随时接受依法实施的监督检查；因乙方安全措施不力或违规作业造成事故的，相应责任及费用由乙方承担。（三）双方现场人员共同执行“自控、互控、他控”保安措施；任何一方发现重大安全隐患，均有权要求立即停止作业并及时通报对方，保障人身与设备安全。', risk_notes = '按过错归责的对称写法；甲方违章指令致害归甲方是inbound关键；法定安全义务不因约定免除。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'safety' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '甲方责任与义务', body_template = '甲方应：（一）按工作界面条款约定按时、按标准提供全部施工条件，并保证所供图纸、地勘及管线资料真实、完整，资料失实导致的损失由甲方承担；（二）在乙方设备就位前完成顶管轴线及高程的复测确认，并向乙方书面移交测量控制点；（三）根据顶进进度保证管材等甲供材料连续供应，因甲方管材供应中断、工作坑或场地不具备条件、手续未办妥造成乙方停窝工的，按停窝工补偿条款承担费用并相应顺延工期；（四）指定驻场代表负责计量签认、签证答复及验收组织，驻场代表变更应书面通知乙方；（五）按本协议约定及时足额支付各期工程款。', risk_notes = '甲方义务与停窝工补偿、顺延条款闭环；驻场代表实名化，防“找不到人签字”导致计量签证停摆。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'party_a_duties' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '乙方责任与义务', body_template = '乙方应：（一）接甲方开工通知后按期组织人员、设备进场，进场前完成设备检修调试，并派技术人员完成开工准备；（二）严格按施工图纸、经批准的施工方案、操作规程与验收规范组织施工，如实填写并妥善保存顶进记录；（三）服从甲方现场统一协调，主动配合甲方及监理的阶段性质量、安全检查；（四）对施工人员进行安全生产、消防及社会治安教育，依法保障劳动者权益；（五）妥善保护已完成品、半成品及甲方设施设备，合理使用甲方提供的水电与场地，因乙方原因造成损坏的负责修复或照价赔偿；（六）施工资料随进度同步整理，竣工验收后移交甲方。', risk_notes = '义务清单适度对称，不含“无条件服从”类表述；顶进记录同时是乙方计量与索赔的证据基础。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'party_b_duties' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '违约责任', body_template = '任何一方违约给对方造成损失的，应承担赔偿责任。甲方逾期付款的，按价款结算与支付条款承担逾期违约金；甲方逾期提供施工条件或逾期付款致乙方无法正常施工累计超过30日的，乙方有权书面催告，催告后10日内仍未纠正的，乙方有权解除本协议，甲方应于解除后15日内结算并支付已完工程量价款、乙方设备进出场费及经签认的停窝工损失。乙方无正当理由逾期完工的，每逾期一日按暂定总价的万分之五向甲方支付违约金，累计以暂定总价的5%为限。约定违约金不足以弥补守约方实际损失的，守约方有权就不足部分继续主张赔偿。', risk_notes = '乙方解除权配“催告＋10日宽限”更易获支持；乙方逾期违约金设5%封顶，双向均衡防被调减。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'breach' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '地质条件与地下障碍物风险', body_template = '甲方提供的地勘报告及地下管线物探资料是乙方施工的依据。施工中遇下列非乙方原因的地质异常情形：地下障碍物（含孤石、旧基础、未探明管线）、实际土质与地勘资料严重不符、承压水或流砂等异常涌水涌砂的，乙方应立即停止顶进，于24小时内书面通知甲方，并采取合理措施防止损失扩大；处理方案由双方会同确定。由此增加的费用（含障碍物处理、工艺调整、设备损耗及停窝工损失）由甲方承担，工期相应顺延，双方以工程联系单据实签认。乙方未及时通知致使损失扩大的，就扩大部分自行承担。', risk_notes = '顶管行业最大风险点：地质异常费用归甲方是inbound必争底线；24小时通知＋防损义务作为对价，条款均衡可谈。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'geology_risk' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '签证与索赔', body_template = '发生设计变更、施工条件变化、甲方指令增加工作内容或其他应由甲方承担责任的事件的，乙方应于事件发生后14日内向甲方提交签证或索赔资料，载明事由、工程量、金额及计算依据；甲方应在收到资料后7日内书面答复，逾期不答复的，视为认可乙方提交的签证或索赔内容。经签认（含视为认可）的签证费用随最近一期进度款一并支付。甲方驻场代表在乙方报送单据上签字确认的，视为甲方签认。乙方逾期提交签证资料的，不影响其依法就实际发生的损失另行主张权利。', risk_notes = '14日提交／7日答复、逾期视为认可是乙方关键程序权利；末句保留法定救济，防“逾期即弃权”反噬。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'claim_visa' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '停窝工补偿', body_template = '因甲方原因（含管材供应不足或中断、工作坑及接收坑不具备条件、施工手续未办妥、场地道路不通、甲供水电中断及甲方指令暂停）造成乙方停窝工的，乙方应于当日书面报告甲方，双方于3日内现场核实并签认停窝工人数、设备台数及起止时间。经签认的停窝工损失按下列标准计取：人员窝工费300元/人·日，设备停滞费800元/台·日（顶管主机按同标准计取），随最近一期进度款一并支付。甲方原因停窝工连续超过15日或累计超过30日的，乙方有权要求撤场，甲方应承担设备退场及再进场费用。', risk_notes = '费率写实（300元/人·日、800元/台·日）＋当日报告3日签认，防“事后算总账”举证僵局；长期停工撤场权与违约解除衔接。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'idle_compensation' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '扣款与异议程序', body_template = '甲方依据本协议对乙方主张扣款、罚款或费用抵扣的，应于扣减前5个工作日书面通知乙方，并附扣减事由、计算依据及相应凭证；乙方有权在收到通知后7个工作日内书面提出异议。异议期内争议部分暂不扣减，由双方在7个工作日内共同核实，核实不成的按争议解决条款处理；无争议部分可先行扣减。未经上述程序的单方扣减无效，乙方有权要求返还，并就被扣减款项按逾期付款主张违约金。甲方单方制作的现场记录、罚款单未经乙方签认的，不得单独作为扣减依据。', risk_notes = '对抗“多处无程序直接扣除”式模版：通知＋凭证＋7个工作日异议期，未经程序扣减无效；单方记录不得单独作为依据。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'deduction_procedure' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '承包方式与工作界面', body_template = '本工程采用包工包设备（顶进作业）方式分包。甲方负责提供：施工图纸及技术交底、顶进工作坑及接收坑、经检验合格的管材（卸至工作坑吊装范围）、施工用水用电接驳点。乙方负责提供：顶管主机及全部辅助顶进设备、起重设备、施工作业人员、减阻注浆材料、管内土方水平运输至工作坑地面，以及完成顶进作业所需的其余全部人机料资源，并对其提供的人员资格、设备安全性能及材料合规性负责。乙方应于进场后3日内对甲方提供的施工条件进行核对并书面确认；未在上述期限内提出书面异议即开始施工的，视为甲方所供条件符合约定。双方工作界面交接以书面签认为准。', risk_notes = 'outbound乙供兜底表述（“其余全部人机料资源”）防漏项加价；进场3日核对＋视为符合，锁定施工条件争议窗口。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'scope_interface' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '工程质量与验收', body_template = '工程质量标准：合格，按国家现行施工及验收规范（含GB 50268）执行。乙方应如实填写顶进记录（顶程、中心线偏差、高程偏差、注浆量）并每日报送甲方，偏差超限时立即纠偏并报告。隐蔽工程覆盖前应通知甲方检查确认；未经检查确认即覆盖的，甲方有权要求剥露复验，复验合格的费用由甲方承担，不合格的费用与工期损失由乙方承担。管道贯通后乙方书面提请验收，甲方在7日内组织验收；验收不合格的，乙方按甲方书面要求限期返工整改，费用由乙方承担，工期不予顺延；整改后仍不合格的，甲方有权另行委托第三方处理，发生的合理费用按扣款与异议程序自应付乙方款项中扣除。', risk_notes = 'outbound不写“逾期视为合格”；顶进数据日报＋隐蔽复验按责分担；第三方处理费扣除挂接异议程序，提高条款存活率。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'quality_acceptance' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '价款结算与支付', body_template = '（一）进度款：施工期间每月25日双方共同计量当月完成的合格工程量并书面签认，甲方于次月15日前支付当月经签认工程量金额的60%。（二）结算款：竣工验收合格且乙方提交完整结算资料、合规增值税发票及农民工工资支付凭证后30日内双方完成结算，甲方将累计付款付至结算总价的97%。（三）质量保证金：预留结算总价的3%，缺陷责任期12个月，期满且无未处理质量问题的，甲方于期满后15日内无息退还；甲方逾期未退的，按逾期付款承担违约责任。乙方未提交农民工工资支付凭证或发票不合规的，相应付款期限顺延，但甲方应一次性书面告知全部补正事项，不得以反复补正拖延付款。', risk_notes = '付款期限独立确定，无以第三方付款为前提的表述；工资凭证与合规发票为合法前置；“一次性告知补正”防条款被认定为拖延工具。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'payment' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '安全施工', body_template = '（一）乙方在其分包作业范围内对施工安全负直接管理责任：遵守安全生产法律法规及标准规范，落实进场安全教育、分部分项安全技术交底、特种作业人员持证上岗、劳保用品穿戴及坑下作业通风、临时用电防护等措施，如实记录并留存备查。（二）甲方依法对施工现场实施统一协调与监督检查，乙方应接受检查并在约定期限内完成隐患整改；存在危及人身安全的重大隐患时，甲方有权责令暂停作业，乙方应立即执行并整改，整改期间的损失由责任方承担。（三）双方现场人员共同执行“自控、互控、他控”保安措施。任何一方均不得以本协议约定免除其依法应承担的安全生产管理义务。', risk_notes = '直接管理责任在乙方＋甲方统一协调义务保留，符合安全生产法分工；停工令用“应立即执行”，避免弃权句式风险。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'safety' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '安全责任承担与追偿', body_template = '因乙方违章作业、安全防护缺失、设备缺陷或现场管理不善造成的安全事故，事故损失及对第三方的赔偿责任由乙方承担；甲方因此依法先行承担或垫付的赔偿款、罚款及处理费用，有权向乙方全额追偿，并有权按扣款与异议程序自应付乙方款项中等额扣除。因甲方指令错误或甲方提供条件缺陷造成的事故，相应责任由甲方承担。双方均有过错的，按各自过错程度分担责任。本条不免除任何一方依法应承担的安全生产管理义务。', risk_notes = '合法传导写法：先行承担＋内部追偿＋按过错分担，不写绝对免责（法定责任不可约定转移）；扣除挂接异议程序。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'safety_transfer' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '农民工工资支付', body_template = '乙方应依法落实农民工实名制管理：人员进出场登记、考勤记录与工资表按月经双方确认后留存备查（至少保存两年），按月足额支付农民工工资，配合落实工资专用账户及维权信息公示要求，并于每月付款申请时向甲方报送上月工资支付凭证。因乙方拖欠农民工工资导致甲方被责令代付、先行垫付或受到行政处罚的，甲方有权按扣款与异议程序自应付乙方款项中扣除代付款项及直接损失，并向乙方追偿；引发群体性事件的，甲方有权按单方解除条款处理。甲方依法代付的农民工工资，视为已向乙方支付同等金额的工程款。', risk_notes = '《保障农民工工资支付条例》合规必备；“代付视为已付”闭环防双重支付；实名制三表口径与机构模版一致。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'farmer_wage' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '甲方责任与义务', body_template = '甲方应：（一）向乙方提供施工图纸、必要的技术资料，并组织设计交底与技术交底；（二）按工作界面条款约定提供施工条件，并协调现场各作业单位的交叉施工；（三）指定驻场代表负责计量签认、验收组织与日常协调，驻场代表变更应书面通知乙方；（四）对工程质量、进度、安全实施检查与监督，但甲方的检查、确认不代替乙方依约应承担的质量与安全责任，亦不免除乙方的整改义务；（五）按本协议约定支付经计量签认的工程款。', risk_notes = '“检查不代替责任”防乙方以甲方已检查已确认抗辩质量责任；甲方义务限于列明范围，不作兜底性承诺。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'party_a_duties' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '乙方责任与义务', body_template = '乙方应：（一）按甲方通知及时组织具备相应资格的人员与检验合格的设备进场，特种作业人员持证上岗；（二）严格按施工图纸、经甲方核准的施工方案、操作规程与验收规范施工，服从甲方现场统一管理与调度；（三）不得将本协议工程转包或违法再分包，不得以挂靠、借用资质等任何形式将主体作业交由他人完成，违反的甲方有权解除本协议并要求赔偿全部损失；（四）依法与其施工人员建立用工关系，承担其人员工资与费用，并缴纳工伤保险或投保团体意外伤害保险；（五）妥善保护现场成品半成品、地下管线及甲方设施，造成损坏的负责修复或照价赔偿；（六）按约报送顶进记录、进度报表及安全资料。', risk_notes = '禁止转包、违法再分包及挂靠显性化（建筑法第28、29条）；用工关系归属乙方，防事实劳动关系争议上移至甲方。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'party_b_duties' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '违约责任', body_template = '乙方无正当理由逾期完工的，每逾期一日按协议暂定总价的万分之五向甲方支付违约金，累计以暂定总价的5%为限；因逾期致甲方对上游发包方承担违约责任的，乙方还应赔偿甲方由此遭受的实际损失。乙方施工质量不合格经书面催告后7日内仍拒不整改，或擅自停工、撤场累计超过7日的，甲方有权解除本协议，已完合格工程量据实结算，由此造成的损失由乙方承担。甲方无正当理由逾期支付经签认工程款的，每逾期一日按未付金额的万分之五向乙方支付违约金。因乙方原因给甲方造成的损失，甲方有权按扣款与异议程序自应付款项中抵扣，不足部分另行追偿。', risk_notes = '双向同为日万分之五、乙方侧5%封顶，均衡设置防整体调减；抵扣统一挂接异议程序是条款存活关键。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'breach' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '地质条件核实义务', body_template = '乙方进场后、开始顶进前，应对甲方提供的地勘报告、地下管线物探资料及现场施工条件进行核对，并书面确认具备顶进条件；乙方未尽核对义务即施工的，因有经验承包人可合理预见的地质情况（含一般土层变化、常规地下水）增加的费用与工期由乙方自行承担。确属地勘及物探资料均无法预见的地下障碍物、严重流砂涌水等重大地质异常，乙方应立即停止顶进并于24小时内书面通知甲方，双方共同核实后另行签认处理方案与费用分担；乙方未及时通知或擅自继续顶进致损失扩大的，扩大部分由乙方自行承担。', risk_notes = '可预见风险归乙方、重大不可预见异常双方签认——完全转嫁有显失公平被否定风险，保留共担出口更稳。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'geology_risk' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '签证与索赔管理', body_template = '未经甲方书面签认的额外工作量、赶工措施或费用增加，甲方不予认可，乙方不得计入结算。乙方主张签证或索赔的，应于事件发生后14日内向甲方提交完整资料，载明事由、工程量、金额及计算依据；逾期提交的，视为放弃该项签证或索赔权利。资料不完整的，甲方应一次性书面告知补正事项，补正期间不计入答复期限；甲方应在收到完整资料后7日内书面答复。仅有甲方现场人员口头指令的，乙方应在实施前取得书面确认；紧急抢险情形除外，但乙方应于抢险结束后7日内补办签证手续。', risk_notes = '“14日逾期视为放弃”约束分包商且期限合理可执行；保留甲方7日答复义务，防单纯免除己方义务被认定格式条款。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'claim_visa' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '履约保证金', body_template = '乙方应于设备进场前向甲方缴纳履约保证金，金额为协议暂定总价的5%，以对公转账方式缴至本协议落款载明的甲方账户，或经甲方书面认可以银行保函形式提供。乙方全面履行本协议且无违约情形的，甲方于竣工验收合格且双方完成结算后15日内无息退还（保函原件同时退回）。乙方违约的，甲方有权按扣款与异议程序自保证金中扣除违约金及损失赔偿，不足部分另行追偿。本协议的成立与生效不以保证金缴纳为前提；乙方逾期未足额缴纳的，甲方有权相应顺延开工日期，顺延产生的工期责任由乙方承担。', risk_notes = '5%处于行业常规区间（招标工程履约保证金上限10%内）；允许保函替代降低乙方资金压力；扣除挂接异议程序。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'performance_bond' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '甲方单方解除权', body_template = '乙方有下列情形之一的，甲方有权书面通知解除本协议并要求乙方赔偿由此造成的损失：（一）将工程转包或违法再分包的；（二）施工质量不合格，经书面催告后7日内仍拒不整改的；（三）擅自停工、撤场累计超过7日的；（四）发生较大及以上安全事故，或存在重大安全隐患经责令整改仍不整改的；（五）拖欠农民工工资引发群体性事件或被行政部门查处的。解除通知到达乙方之日本协议解除。解除后7日内，乙方应撤出人员设备，向甲方移交施工现场及全部施工资料；已完合格工程量据实结算，与乙方应承担的违约金及损失一并清算。乙方逾期不退场的，甲方有权自行组织清场，费用由乙方承担。', risk_notes = '解除情形清单化＋质量项设催告前置，降低解除权滥用之嫌；自行清场权是处置僵局的关键抓手。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'unilateral_termination' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '反索赔与损失抵扣', body_template = '因乙方原因造成工期延误、质量缺陷、安全事故、环保处罚，或导致甲方对上游发包方、监理单位及其他第三方承担违约或赔偿责任的，甲方有权就实际发生的损失（含对外支付的赔偿款、罚款、返工修复费用及合理的鉴定费、律师费）向乙方主张赔偿，并有权按扣款与异议程序自应付乙方的任何款项（含履约保证金、质量保证金）中予以抵扣；抵扣不足部分，甲方保留继续追偿的权利。甲方主张损失时，应向乙方提供相应的支付凭证、处罚决定或生效法律文书等证明材料。', risk_notes = '抵扣范围扩展至保证金、质保金但统一挂接异议程序；甲方负举证义务使条款更可执行，免“漫天反索赔”之嫌。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'counter_claim' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '扣款与异议程序', body_template = '甲方依据本协议对乙方主张扣款、罚款或费用抵扣的，应书面通知乙方，并附扣减事由、计算依据及相应凭证；乙方可在收到通知后5个工作日内书面提出异议，甲方应对异议进行核实并书面回复。乙方逾期未提出异议，或异议经核实不成立的，甲方有权自应付款项中直接扣减；异议成立的部分不予扣减。乙方对核实结果仍有争议的，可按争议解决条款处理，但无争议部分的扣减与付款不受影响；争议解决期间，甲方就争议金额可暂缓支付，其余到期款项应正常支付。', risk_notes = 'outbound保留扣款权但配最低程序（通知＋凭证＋5个工作日异议期），防整条扣款权因无程序被整体否定。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'deduction_procedure' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '价款结算与支付（月度计量简版）', body_template = '本工程不设启动款。施工期间每月25日双方共同计量当月完成工程量并书面签认，甲方于次月15日前支付当月经签认工程量金额的60%；竣工验收合格后30日内双方完成结算，甲方于结算完成后15日内一次性付清全部剩余价款，不预留质量保证金。甲方的付款义务独立存在，不以甲方收到任何第三方（含建设单位）款项为前提，最迟应于对应工程量计量签认后60日内付清该期款项。甲方逾期付款的，每逾期一日按未付金额的万分之五向乙方支付违约金；逾期超过30日的，乙方有权暂停施工并要求甲方先行支付全部到期款项，由此增加的费用与工期由甲方承担。', risk_notes = '适用无启动款、纯月度计量的短平快项目；不设质保金、结算后一次付清；保留“签认后60日兜底”与日万分之五逾期违约金。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'pipe_jacking' AND section_key = 'payment' AND direction = 'inbound' AND variant_key = 'monthly_simple';

UPDATE contract_clause_template SET title = '首部与签约依据', body_template = '甲方（承租方）：{{party_a}}，统一社会信用代码：{{party_a_credit_code}}。
乙方（出租方）：{{party_b}}，统一社会信用代码：{{party_b_credit_code}}。
根据《中华人民共和国民法典》及相关法律法规，甲乙双方就{{project_name}}所需机械设备租赁（含配套作业服务）事宜，遵循平等、自愿、公平、诚实信用原则，经协商一致订立本合同，共同遵照履行。本合同项下设备的名称、规格型号、数量、单价以《设备清单》为准，《设备清单》、进出场交接单及双方签认的台班记录均为本合同不可分割的组成部分，与本合同具有同等效力。', risk_notes = '设备族固定甲方=承租方、乙方=出租方；inbound 我方为乙方（出租收款），outbound 我方为甲方（承租付款）。《设备清单》与交接单、台班记录并入合同组成部分，防止结算时被抗辩为无约束力单据。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'parties_basis' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '设备清单与计价', body_template = '租赁设备以《设备清单》为准，逐台载明：设备名称、规格型号、绑定工作内容、计价单位（台班/月）、数量、含税单价，并在『是否含操作人员』栏显式标注（{{with_operator}}）；标注为含的，操作人员人工费已包含在对应单价内，不另行计取。设备经双方共同验收合格并签署《进场交接单》后起算租金。按台班计价的，8小时为一个台班，单日作业不足4小时按半个台班计，超过4小时不足8小时按一个台班计，夜间连续作业由双方现场代表当日另行签认；按月计价的，不足一个月部分以月租金的三十分之一折算日租金。合同暂定总价人民币{{amount}}元（大写：{{amount_cn}}），最终以双方逐日签认的台班记录及工作量为结算依据，多退少补。', risk_notes = '『是否含操作人员』必须显式标注——样本合同『不含司机』字面与台班含人工实质矛盾，是结算争议高发点；台班折算（8小时制、半台班规则）与月租折日规则烘焙为默认值，防口头折算扯皮。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'equipment_schedule' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '租期与计费起止', body_template = '租赁期限自{{start_date}}起至{{end_date}}止。租金自设备进场并经双方验收合格、签署《进场交接单》之日起算。提前退租的，承租方应提前3日书面通知出租方，租金计至设备实际退场之日止；承租方已按约通知且现场具备退场条件，因出租方原因迟延撤场的，自通知载明退场日的次日起不计租金。租期届满需续租的，双方应于期满前3日书面确认续租期限与单价；未续签而承租方继续使用设备、出租方未提出异议的，本合同继续有效，租期转为不定期，任何一方均可提前3日书面通知对方终止租赁，结算至设备实际退场之日。', risk_notes = '『提前3日书面通知+计至实际退场日』双层计费结构：防承租方『通知到达即停止计费、设备滞留现场』的时间差损失；反向补『出租方迟延撤场不计租』，both 立场保持对称。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'lease_term' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '进出场', body_template = '设备进出场（含运输、装卸、安拆）费用由承租方承担，以进场、退场各一次为限。因承租方原因（含场地不具备进场条件、工作面调整、指令转场）增加进出场或场内转移次数的，增加的费用由承租方另行承担；因出租方原因（含交付设备与《设备清单》不符被退回）发生的进出场费用，由出租方承担。设备进出场时间以双方签署的交接单为准。承租方应提供满足设备运输、进出场及安拆作业要求的道路、场地与配合条件；大型设备安拆所需辅助机械及特殊措施费用的承担方式在《设备清单》中逐台约定。', risk_notes = '大型设备（顶管机/吊车）二次进出场成本高，默认承租方承担一次+按归因加收，双向归因防扯皮；辅助机械费下沉到《设备清单》逐台约定，避免正文一刀切。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'entry_exit' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '计费与停滞补偿', body_template = '设备台班以双方现场代表逐日签认的台班记录为准；承租方收到台班记录后2日内既不签认亦不书面提出异议的，视为认可。因承租方原因（含现场不具备作业条件、交叉施工干扰、指令等待、甲供配套不到位、相关手续未办妥等）造成设备在场停滞的，自停滞之日起按该设备台班含税单价的50%计取停滞补偿费（元/台·日）；承租方要求操作人员留守现场的，留守期间人工费照计。连续停滞超过7日的，出租方有权书面通知撤场，承租方应在设备退场前结清全部已发生租金、停滞补偿费及进出场费用，撤场不影响出租方就已发生债权继续主张。因不可抗力停工的，停工期间租金减半计取，租期相应顺延；不可抗力持续超过15日的，双方均有权书面解除本合同，互不追究违约责任。', risk_notes = 'inbound 必争条款：样本最大空白即无窝工保底——『未作业不计费』叠加甲方随时叫停，闲置成本全压出租方。停滞费按台班单价50%/台·日+连续7日撤场权+撤场不消灭既有债权，是三道保底；不可抗力减半计租体现设备在场占用成本。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'billing_idle' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '计费与停机处理', body_template = '设备按双方现场代表签认的实际作业台班计费，未作业时段不计费；未经承租方现场代表签认的台班记录，不作为结算依据。设备发生故障或性能不能满足《设备清单》约定工作内容的，出租方应在接到通知后4小时内响应处理；24小时内未修复的，故障停机时段不计费，租期相应顺延。同一设备连续故障停机超过5日，或一个月内累计故障停机超过10日的，承租方有权要求出租方无偿更换同等及以上性能的设备，或书面解除本合同并要求退还已付而未使用部分的租金。因出租方设备证照不齐、检验过期导致停工或被主管部门查处的，停工期间不计租金，由此给承租方造成的损失由出租方承担。因不可抗力停工的，停工期间不计租金，租期相应顺延；持续超过15日的，双方均有权书面解除本合同。', risk_notes = 'outbound 立场三件套：未作业不计费+故障4小时响应/24小时未修复不计费顺延+连续5日或月累计10日触发更换与解除权；证照瑕疵停工损失归出租方；不可抗力期间不计租。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'billing_idle' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '操作人员与作业责任', body_template = '设备配备操作人员的，出租方保证操作人员持有效特种作业操作资格证书上岗，遵守施工现场安全管理制度，服从承租方的统一调度与作业安排；操作人员人工费是否包含在单价内，以《设备清单》『是否含操作人员』栏（{{with_operator}}）标注为准，标注为含的不另行计取。承租方应向操作人员进行安全技术交底，并提供具备安全作业条件的工作面。因承租方违章指挥、强令冒险作业或工作面不具备安全作业条件导致的事故及损失，由承租方承担；因操作人员违规操作导致的事故及损失，由出租方承担；双方均有过错的，按过错程度分担。操作人员有权拒绝违章指挥，由此造成的设备停滞按本合同停滞补偿条款处理。', risk_notes = '湿租（带人作业）责任对称划分：违章指挥、工作面缺陷归承租方，违规操作归出租方，双过错按比例分担——样本合同将『一切安全事故』整体压给出租方属需谈判修正项；拒绝违章指挥衔接停滞补偿，防『一拒绝就停计费』。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'operator_duty' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '操作人员与作业责任', body_template = '设备配备操作人员的，出租方保证操作人员具备相应特种作业操作资格并持证上岗，进场前向承租方提交资格证书复印件备查，接受承租方的安全交底与现场管理；操作人员人工费是否包含在单价内，以《设备清单》『是否含操作人员』栏（{{with_operator}}）标注为准。操作人员的劳动关系、工资支付、社会保险及工伤保险责任均由出租方承担，出租方应为设备及作业投保相应保险。因出租方操作人员违规操作、无证作业或设备自身缺陷导致的人身伤亡、财产损失及对第三方的损害，由出租方承担赔偿责任；因承租方指令错误导致的损失，由承租方承担相应责任。操作人员不能胜任作业或多次违反现场管理规定的，承租方有权要求出租方在24小时内更换合格人员。', risk_notes = 'outbound 镜像：设备缺陷与违规操作归出租方；劳动关系、工资、社保、工伤整体隔离在出租方侧+投保义务，防用工连带；24小时换人权保障工效。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'operator_duty' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '维修保养与燃油', body_template = '设备日常保养、维修及易损件更换由出租方负责并承担费用，因承租方使用不当或其指令原因造成的损坏除外；燃油、辅油由承租方供应并承担费用，承租方应保证油品符合设备要求，因油品不合格造成的设备损坏由承租方负责。设备发生故障的，出租方应在接到通知后4小时内响应并及时修复，保障施工正常进行；出租方进行例行保养应提前与承租方协商安排时间，尽量利用非作业时段进行，因保养造成的停机时段不计租金。设备的定期检验、登记及机动车辆保险等法定手续由出租方办理并承担费用，相关证照资料随机移交或备查。', risk_notes = '维保归出租方、燃油归承租方是台班租赁行业默认分工；保养停机不计租+检验保险证照义务归出租方，补齐样本空白；油品质量责任防低价劣油损机争议。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'maintenance' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '设备损坏、丢失与风险', body_template = '自《进场交接单》签署至设备退场交接前，承租方对设备负妥善保管义务，夜间及停工期间应落实现场看护措施。因承租方原因（含保管不善、违章使用、超负荷作业、现场管理缺失）造成设备损坏的，由承租方承担修复费用，修复期间租金照计；造成设备丢失、被盗或灭失的，承租方应按双方确认的设备价值赔偿，协商不成的，按同型号同年限设备重置成本扣减合理折旧确定，并按该设备台班含税单价的50%赔偿出租方停租损失，计至赔偿款付清之日、最长计30日。正常磨损由出租方自行承担。未经出租方书面同意，承租方不得将设备转租、出借、抵押或移作本合同约定以外的用途。因不可抗力造成设备毁损灭失的，损失按保险理赔及法律规定处理，双方互不追究违约责任。', risk_notes = '样本合同设备丢失/被盗责任完全空白——inbound 必须补齐：修复期租金照计+灭失按重置成本扣折旧+停租损失封顶30日形成完整闭环；禁转租出借抵押保所有权。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'damage_loss' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '设备损坏、丢失与风险', body_template = '设备进场交接后，承租方在其保管范围内对设备尽合理保管义务。因承租方过错造成设备损坏的，按修复所需的合理费用赔偿；确无修复价值或灭失的，按设备实际价值（同型号同年限市场价值扣减折旧）赔偿；正常磨损、设备自身缺陷、自然老化及出租方操作人员原因造成的损坏，承租方不承担赔偿责任；出租方已获得保险理赔的部分，在赔偿金额中相应扣减。出租方保证对设备享有完整的所有权或处分权，设备不存在查封、扣押、抵押或权属争议等情形；因权属瑕疵或第三人主张权利导致承租方停工或遭受损失的，出租方应赔偿由此造成的全部直接损失。租赁期间设备折旧、贬值由出租方自行承担。', risk_notes = 'outbound 立场：赔偿以过错+实际损失为限，排除正常磨损、自身缺陷与出租方人员原因；保险理赔先行扣减防双重受偿；权属瑕疵担保+停工赔偿防『租到查封设备』。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'damage_loss' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '安全管理', body_template = '双方按各自职责与过错承担安全责任。承租方作为施工现场统一管理方，依法履行现场安全生产管理职责，向出租方及其操作人员进行安全技术交底，提供符合安全要求的作业环境与临时用电条件；出租方保证设备安全性能合格、安全防护与警示装置齐全有效，其进场人员遵守现场安全规章制度并正确使用劳动防护用品。起重吊装、有限空间配合作业等危险作业前，双方应共同确认专项方案与警戒措施后方可实施。任何一方不得以合同约定免除其依法应承担的安全生产管理义务；发生安全事故的，按《中华人民共和国安全生产法》及相关规定处理，由责任方按其过错承担相应责任，双方应先行配合抢险救助。', risk_notes = '法定安全责任不可约定转移（规则层红线拦截项），按『现场统一管理归承租方+设备本质安全归出租方+各自过错分担』三分结构；危险作业双确认程序补齐样本空白。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'safety' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '租金结算与支付', body_template = '双方于每月25日按签认的台班记录及工作量核对当期租金并出具对账单，承租方应于次月15日前支付经核对的当期租金。承租方的付款义务独立存在，不得以第三方付款情况作为向出租方支付租金的前提；无论承租方与任何第三方之间的结算进度如何，当期租金最迟应于当期计量签认后60日内付清。承租方逾期付款的，每逾期一日按未付金额的万分之五向出租方支付违约金；逾期超过30日的，出租方有权书面通知暂停设备作业或撤场，由此增加的费用及损失由承租方承担，且不影响出租方就已发生租金及违约金继续主张。双方约定质量保证金的，比例不超过结算总额的3%，于设备退场并完成结算后15日内一次性无息退还。', risk_notes = 'inbound 核心：付款独立条款+计量签认后60日兜底最晚付款日（司法口径：第三方付款前置只能解释为付款期限合理顺延而非永久免除）；逾期万分之五/日+逾期30日停机撤场自救权；质保金3%上限+退场结算后15日返还，补样本『3%无返还期限』缺口。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'payment' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '租金结算与支付', body_template = '双方于每月25日按现场签认的台班记录核对当期租金，经承租方复核确认后，承租方于次月15日前支付当期租金；未经签认或对账存在争议的部分可暂缓支付且不视为违约，无争议部分应按期支付。出租方应在收款前按约定提供合规增值税发票，发票品目、税率与合同性质一致；未提供合规发票的，承租方有权顺延相应部分的付款期限，补齐后恢复计算。承租方对出租方的结算主张有异议的，应于收到对账单后5个工作日内书面提出并说明理由，逾期未提出的视为认可。承租方主张扣款的（含停机不计费、损坏赔偿、代垫费用），应书面通知出租方并附相应凭证，出租方可在5个工作日内书面异议，经双方核实后在当期应付租金中据实扣减。', risk_notes = 'outbound 立场：付款以签认+复核为准、争议部分暂缓不构成违约；先票后款+顺延机制；扣款程序化（书面通知+凭证+5个工作日双向异议期）对抗样本『7处有权直接扣除、拒签按甲方记录为准』式条款。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'payment' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '发票与税务', body_template = '出租方按{{tax_rate}}%税率向承租方开具增值税{{invoice_type}}发票，发票品目必须与合同实质一致：（一）纯设备租赁（不含操作人员）的，按『有形动产经营租赁服务』品目开具，出租方为一般纳税人的适用13%税率，为小规模纳税人或依法选择简易计税的适用3%征收率；（二）设备配备操作人员并按台班或工作量作业的，属于提供建筑服务，按『建筑服务』品目开具，一般计税适用9%税率，简易计税适用3%征收率，并在发票备注栏注明建筑服务发生地及项目名称。发票仅向本合同相对方开具，做到合同、资金、发票三流一致；国家税率调整的，自调整生效之日起按新税率执行，含税单价中的不含税金额保持不变。任何一方不得要求对方虚开发票或变更品目开具。', risk_notes = '干租=有形动产经营租赁13%（一般纳税人）/3%（小规模简易），湿租带人作业=建筑服务9%（一般计税）/3%（简易计税）——品目错配是『名租实工』样本的核心税务风险；建筑服务发票备注栏注明发生地为合规要件；税率调整按价税分离处理。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'invoice_tax' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '违约责任', body_template = '出租方未按约定时间交付合格设备，或交付设备与《设备清单》不符且未在约定期限内更换的，每迟延一日按迟延部分对应租金（按月计租的，以月租金的三十分之一折算日租金）的千分之一向承租方支付违约金；承租方迟延支付租金的违约责任，按本合同『租金结算与支付』条款执行。上述各项迟延违约金累计均以对应迟延金额的20%为上限；违约金不足以弥补守约方实际损失的，守约方有权就不足部分继续主张赔偿。一方根本违约致使合同目的不能实现的，守约方有权书面解除本合同，并要求违约方赔偿损失。本条违约金与本合同约定的停滞补偿费、故障停机不计费为不同性质款项，互不重复计算、互不抵销冲抵。', risk_notes = '双向对等费率（迟延按日千分之一）+累计20%封顶+损失差额可续主张：对抗样本『甲方活期利率封顶2%、乙方多档不封顶』的不对称结构；付款迟延引致『租金结算与支付』条款，避免双套费率冲突；与停滞费/停机不计费互斥防双重计罚。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'breach' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '送达条款', body_template = '双方确认本合同首部及落款载明的地址为有效送达地址，适用于履约通知、对账单、催告函等非诉文书以及争议解决全部阶段（含一审、二审、再审、执行程序）司法文书的送达。一方送达地址、指定收件人或联系方式变更的，应于变更后7日内书面通知对方；未依约通知的，向原地址送达仍发生送达效力，由此产生的不利后果由变更方自行承担。以邮寄方式送达的，交邮后第三日视为送达；以专人送达的，签收之日视为送达，受送达人拒绝签收的，送达人以拍照、录像等方式记明情况后即视为送达；发送至双方确认的电子邮箱或即时通讯账号的，信息发送成功之日视为送达。', risk_notes = '覆盖非诉+诉讼全阶段（含再审、执行）的送达效力条款，绝大多数样本合同缺失；拒收记录视为送达+电子送达并轨，压缩『躲送达』拖延空间。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'service_notice' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '争议解决', body_template = '因本合同及其履行发生的争议，双方应先友好协商解决；协商不成的，任何一方均有权向合同签订地有管辖权的人民法院提起诉讼。争议解决期间，除争议事项外，本合同其余部分双方应继续履行，双方均应采取合理措施防止损失扩大，怠于采取措施致使损失扩大的，就扩大部分不得向对方主张赔偿。守约方为实现债权而支出的合理律师费、诉讼费、保全费、保全担保费、公证费及差旅费，由违约方承担。', risk_notes = '管辖烘焙为合同签订地（签订地通常可由我方安排），避免样本『甲方住所地』单边管辖；减损义务为民法典法定规则的重申；实现债权费用转由违约方承担，提高对方违约成本。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'dispute' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '其他与生效', body_template = '本合同自双方盖章并经法定代表人或授权代理人签字之日起生效。本合同一式肆份，甲方执贰份、乙方执贰份，具有同等法律效力；《设备清单》、进出场交接单及双方签认的台班记录、对账单均为本合同组成部分。未尽事宜由双方另行签订书面补充协议，补充协议与本合同具有同等效力，约定不一致的，以在后签订者为准。本合同任何空白栏目应在用印前填写完整或以横线划除，留白视为对相应事项未作约定，任何一方不得在留白处单方补记内容并据以主张权利。任何一方变更名称、法定代表人或联系人的，不影响本合同效力，但应及时书面告知对方。', risk_notes = '『留白视为未约定+禁单方补记』源自样本教训：已盖章合同出现7处关键商业条款留白；附件清单逐项并入合同组成部分；补充协议冲突以在后者为准，明确文件优先序。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'misc_effective' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '落款', body_template = '甲方（盖章）：{{party_a}}
法定代表人/委托代理人：{{party_a_legal_person}}
统一社会信用代码：{{party_a_credit_code}}
开户银行：{{party_a_bank_name}}
账号：{{party_a_bank_account}}
签约日期：{{sign_date}}

乙方（盖章）：{{party_b}}
法定代表人/委托代理人：{{party_b_legal_person}}
统一社会信用代码：{{party_b_credit_code}}
开户银行：{{party_b_bank_name}}
账号：{{party_b_bank_account}}
签约日期：{{sign_date}}

双方的收款、付款均应通过本落款载明的账户进行；账户变更的，须经变更方加盖公章书面通知对方后方为有效，未经有效通知向原账户付款的视为适当履行。', risk_notes = '双方对称列示法定代表人/委托代理人与银行账户；『付款只认落款账户+账户变更须盖章书面通知』是防冒名指令变更收款账户诈骗的默认防线。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'signature_block' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '设备清单与计价（纯干租）', body_template = '租赁设备以《设备清单》为准，逐台载明设备名称、规格型号、计价单位（台班/月）、数量与含税单价。本合同为纯设备租赁（不含操作人员），承租方自行配备持有效特种作业操作资格证书的操作人员，并承担相应的用工责任与作业组织责任；出租方对设备性能合格与权属清晰负责，设备进场时随机移交合格证明、定期检验记录及安全操作规程。设备经双方共同验收合格并签署《进场交接单》后起算租金；按台班计价的，8小时为一个台班，单日使用不足4小时按半个台班计，超过4小时不足8小时按一个台班计；按月计价的，不足一个月部分以月租金的三十分之一折算日租金。合同暂定总价人民币{{amount}}元（大写：{{amount_cn}}），最终按双方签认的实际使用量结算，多退少补。本合同项下租赁属『有形动产经营租赁服务』，发票按本合同发票与税务条款第（一）项对应品目及税率开具。', risk_notes = '干租版：操作人员配备与用工责任整体在承租方侧，出租方交付合格证明、检验记录与操作规程后完成随附义务；发票固定走有形动产经营租赁品目（一般纳税人13%/小规模简易3%）；台班折算与月租折日规则同默认版。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'equipment_lease' AND section_key = 'equipment_schedule' AND direction = 'both' AND variant_key = 'dry_lease';

UPDATE contract_clause_template SET title = '首部与签约依据', body_template = '甲方（发包人）：{{party_a}}，统一社会信用代码：{{party_a_credit_code}}。
乙方（劳务承包人）：{{party_b}}，统一社会信用代码：{{party_b_credit_code}}。
依据《中华人民共和国民法典》《中华人民共和国建筑法》《保障农民工工资支付条例》及现行有关规定，甲乙双方遵循平等、自愿、公平、诚信原则，就{{project_name}}劳务作业事宜协商一致，订立本合同。乙方确认其为依法设立、能够独立承担民事责任并具备完成本合同劳务作业相应能力与用工条件的主体。双方确认各自签约经办人均已取得有效授权，所盖印章与本合同载明的主体名称一致；以项目部印章或个人名义签署的文件，未经授权确认对签署方不发生效力。', risk_notes = '签约依据仅引用现行有效法律（民法典/建筑法/农民工工资条例），不引用已废止文件；印章与授权唯一性确认对应样本机构模版的授权风险提示书机制。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'parties_basis' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '劳务作业范围与内容', body_template = '劳务作业范围：{{work_scope}}。具体作业内容与工作界面以双方签认的作业清单及施工图纸为准。甲方指令增加或变更作业内容的，按签证程序办理，由双方现场代表书面签认后据实计价，签证单应于相应作业完成后7日内办理完毕。乙方仅提供劳务作业及配套小型机具，不承包主要材料；乙方不得将本合同劳务作业转包或再分包。作业质量应符合现行国家、行业验收规范及设计文件要求；因乙方原因造成质量不合格的，乙方负责无偿返工，返工人工费用由乙方承担。甲方对当期作业质量的异议，应于当期计量确认时或计量确认后5个工作日内书面提出；隐蔽部位复验及缺陷责任期内发现的质量缺陷除外。', risk_notes = '范围清单化+签证7日办结，防清包工模式下"顺手活"无偿扩张与口头指令无据；质量异议期锚定计量节点并设固定天数，杜绝"自发现之日起"式无限敞口；劳务转包为法定红线，双向立场均需禁止。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'scope_content' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '计价方式与合同价款', body_template = '本合同按清包工综合单价计价：{{unit_price_desc}}。合同暂估总价人民币{{amount}}元（大写：{{amount_cn}}），最终结算价按双方签认的实际完成作业量乘以综合单价据实计算，多退少补。综合单价已包含人工工资、加班费及各项津贴、劳动保护费、小型机具与工具用具使用费、现场配合费、管理费、利润及税费等全部费用，除经签证确认的变更外不作调整。签证变更部分有相应单价的按合同单价执行，无相应单价的由双方参照签约时市场人工价格水平协商确定。作业量以双方现场代表共同签认的计量记录为准；任何一方的单方记录未经对方签认且无其他有效证据印证的，不作为结算的计量凭据。', risk_notes = '综合单价包含范围逐项列明，防结算阶段二次收费争议；"单方记录不作结算凭据"对冲样本"拒签则按甲方记录为准"套路；大写金额由系统后端生成，AI不改动数字（对照样本同一合同两处大写互相矛盾的事故）。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'quantity_pricing' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '作业期限', body_template = '计划作业期限自{{start_date}}起至{{end_date}}止，按日历天计算（含法定节假日）。甲方应于开工前向乙方移交具备作业条件的作业面并完成安全技术交底，未按期移交或交底的，作业期限相应顺延。因甲方原因、设计变更、甲供材料未按期到位或不可抗力导致停工的，作业期限相应顺延，顺延天数以双方签认的现场记录为准；乙方应于相关情形发生后3日内书面提出顺延申请并附证明材料，甲方应于收到后5个工作日内书面答复，逾期未答复的视为认可该项顺延。因乙方原因造成进度滞后的不予顺延，乙方应自行采取赶工措施，由此增加的费用由乙方承担。', risk_notes = '顺延程序双向闭环（3日申请+5个工作日答复+逾期视为认可），避免口头顺延无据可查；作业面移交与交底作为开工前置义务，为工期违约归责提供锚点。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'duration' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '劳务人员与实名制', body_template = '乙方投入劳务人员约{{worker_count}}人，均应年满18周岁、符合建筑施工作业年龄要求且身体健康，特种作业人员持有效资格证书上岗。乙方人员由乙方直接管理并支付劳动报酬，与甲方之间不建立劳动关系。双方按规定落实实名制管理：人员进退场登记、每日考勤，《考勤表》《工资表》《施工作业人员周统计表》由双方现场代表按期签认、各执一份留存，工资支付台账至少保存三年备查。乙方更换现场负责人或成建制调整作业班组的，应提前3日书面通知甲方；对不服从现场管理或违章作业的人员，甲方有权要求乙方限期撤换。双方获取的人员信息仅用于本项目实名制与合规管理，不得挪作他用。', risk_notes = '实名制三表体系（考勤表/工资表/周统计表）源自样本机构模版合规级流程；工资台账保存三年为《保障农民工工资支付条例》第28条法定期限；年龄门槛烘焙为18周岁——建筑施工属未成年工禁忌劳动，16周岁写法有合规瑕疵；人员信息最小化条款为我方补充。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'personnel' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '材料与机具供应', body_template = '本合同作业所需主要材料、周转材料及大型机械设备由甲方提供，具体以双方签认的进场交接单为准；乙方自备一般作业工具及小型机具，机具应性能完好、符合安全要求，进场前报甲方查验登记。甲供材料由双方共同清点、书面签认后交乙方领用，乙方应妥善保管、合理使用、限额领料；实际损耗超过双方签认的损耗控制标准的，超出部分按甲供材料实际采购价格在结算中据实扣减，不另行计收罚金或管理费，扣减按本合同扣款程序办理。剩余材料及可回收废旧料按甲方指定方式退库或移交。乙方自备机具由乙方自行保管，因甲方原因造成损坏的，由甲方承担修复费用。', risk_notes = '保留样本损耗率控制表思路（分品类设上限、结算核对），但剔除其"超耗另加5%罚金"的双重处罚；超耗只按采购价据实扣减且必须走扣款程序，防止演变为无程序罚款入口。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'materials_tools' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '劳务费结算与支付', body_template = '双方于每月25日共同计量并书面确认当月完成作业量；甲方于次月15日前支付经确认劳务费的80%。甲方按本合同付款系其独立合同义务，不受甲方与建设单位或任何第三方之间款项收付情况的影响；当期应付劳务费扣除按本合同程序确认的应扣款项后，最迟应于当期计量确认后30日内付清。全部作业完成并经验收合格后30日内，甲方结清全部劳务费尾款。如双方另行书面约定质保金的，累计不超过结算总额的3%，且不得从涉及农民工工资的部分中扣留；缺陷责任期为6个月，自验收合格之日起算，期满后14日内无息退还。甲方逾期付款的，按未付金额的日万分之五向乙方计付违约金，直至实际付清之日止。', risk_notes = 'inbound三道防线：付款义务独立化+计量确认后30日兜底付清（呼应最高法2024年对中小企业条款的否定口径，甲方以第三方付款状况拖延的空间被封死）；质保金上限3%且隔离工资部分（对照样本LW合同扣留20%质保金的教训）；逾期付款日万分之五与乙方违约费率完全对等。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'payment' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '劳务费结算与支付', body_template = '双方于每月25日共同计量并书面确认当月完成作业量。乙方应随计量资料提交经签认的当月《考勤表》《工资表》及上期农民工工资发放凭证；资料齐备后，甲方于次月15日前支付经确认劳务费的80%。全部作业完成并经验收合格、乙方结清农民工工资并提交全部支付凭证后30日内，甲方结清尾款。如双方书面约定质保金的，累计不超过结算总额的3%，不得从涉及农民工工资的部分中扣留；缺陷责任期为6个月，自验收合格之日起算，期满后14日内无息退还。甲方对乙方主张任何扣款的，应于扣减前书面通知并附计算清单与凭证，乙方有5个工作日异议期，异议期内争议部分暂不扣减，无争议部分按期支付。', risk_notes = 'outbound立场：工资凭证前置是《保障农民工工资支付条例》框架下合法且必要的支付管理措施，与背靠背性质不同；扣款程序（书面通知+5个工作日异议期）与inbound口径完全一致，保持公司双向公平口径，降低条款被认定显失公平的风险。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'payment' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '农民工工资支付', body_template = '乙方依法承担其劳务人员的工资支付主体责任，按月足额支付农民工工资，落实实名制、工资专用账户及按项目参保等规定；涉及施工总承包单位代发工资的，乙方应及时报送考勤与工资清单并配合代发。乙方应按甲方要求提供工资发放凭证备查，并配合在项目现场醒目位置进行维权信息公示。因乙方拖欠农民工工资导致甲方被责令先行清偿或垫付的，甲方有权就实际垫付金额从应付乙方款项中等额扣除，不足部分向乙方追偿；由此产生的行政处罚及信用惩戒后果由责任方承担。任何情况下，涉及农民工工资的款项不附加任何支付条件，不得用于抵扣其他债务，亦不得作为质保金扣留。', risk_notes = '工资款"三不"（不附条件/不抵扣/不留质保）双向通用：inbound保护我方劳务收款中的工资部分不被任何安排截留，outbound隔离我方作为发包方的连带清偿风险；垫付扣除+追偿对应条例先行清偿机制；异地项目可在style_ref层引用属地工资保证金文件。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'farmer_wage' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '窝工与停工', body_template = '因甲方原因（含作业面不具备条件、甲供材料未按期到位、等待图纸或指令、甲方要求停工等）造成乙方人员窝工的，乙方应于当日向甲方现场代表书面报告窝工人数及原因，双方于当日或次日签认；经签认的窝工按300元/人·日计取窝工费，随当期劳务费一并支付。甲方收到报告后未签认亦未于2个工作日内书面提出异议的，以乙方书面报告并经考勤记录印证的人数为准。因甲方原因连续停工超过15日的，乙方有权要求对已完成作业量先行计量结算，并可选择撤场，撤场及此后再进场的费用由甲方承担。因不可抗力停工的，双方各自承担自身损失。', risk_notes = '对照样本"仅赔窝工费且排除其他违约责任"的空转条款：费率（300元/人·日）、当日报告+签认程序、随当期支付三要素齐备才可执行；"未答复视为认可报告人数"防甲方拖签冷处理；连续停工15日撤场权是inbound止损底线。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'idle_compensation' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '安全生产与文明施工', body_template = '甲方作为现场统一管理方，依法履行安全生产管理、进场安全教育与安全技术交底义务，提供符合安全生产条件的作业环境；乙方遵守现场各项安全与文明施工规定，落实班前教育、劳保用品配备穿戴及特种作业持证上岗要求，接受安全检查并对查出隐患按期整改。发生生产安全事故的，依照法律法规并按双方过错程度确定责任承担，任何一方均不得以合同约定免除其法定安全生产义务。乙方应为全部进场人员办理工伤保险或团体人身意外伤害保险并承担费用；未投保导致的赔偿由乙方承担，但不免除甲方依法应负的责任。乙方负责作业区域工完场清，垃圾按甲方指定地点堆放、清运。', risk_notes = '对照样本"事故一律与发包方无关、责任固定压给作业方"的无效倾向条款：改为法定义务不可让渡+按过错分担，双向立场下均经得起效力审查；保险双轨（工伤或团体意外险）保障赔付能力，是双方共同的风险缓冲。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'safety' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '违约责任', body_template = '乙方无正当理由迟延完成作业的，按合同暂估总价的日万分之五向甲方计付违约金；该项违约金累计以合同暂估总价的5%为限。甲方逾期支付经确认劳务费的，按未付金额的日万分之五向乙方计付违约金，直至实际付清之日止。一方违约给对方造成的损失超过已付违约金的，守约方有权就不足部分继续主张赔偿。乙方擅自转包或再分包劳务作业、拖欠农民工工资经书面催告后7日内仍未改正，或发生重大质量、安全违约的，甲方有权书面解除本合同，双方对已完成的合格作业量据实结算；甲方逾期付款超过30日经书面催告后7日内仍未支付的，乙方有权书面解除本合同，并要求结清已完成合格作业量的全部劳务费。', risk_notes = '双向同费率（日万分之五）同规则，对照样本"乙方多档不封顶、甲方付款免责"的单向不对称罚则；完工迟延封顶5%、金钱债务逾期不封顶符合通行裁判口径；解除权双向配置——outbound覆盖转包/欠薪/重大违约的单方解除情形，inbound覆盖持续拒付时的撤场止损。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'breach' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '扣款与异议程序', body_template = '甲方基于本合同对乙方主张任何扣款、罚款或费用分摊的，应于实际扣减前5个工作日书面通知乙方，载明事由、金额、计算过程并附相应凭证；乙方自收到通知之日起5个工作日内有权书面提出异议，异议期内争议部分暂不扣减，无争议部分的支付不受影响。双方应于异议提出后10日内协商核对；协商不成的，按本合同争议解决条款处理，处理期间甲方不得就争议部分单方扣减。未经上述程序的单方扣减，乙方有权要求全额返还，并按逾期付款约定计付违约金。甲方的单方检查记录、罚款单未经乙方签认且无其他有效证据印证的，不作为扣款凭据；乙方拒绝签字本身不视为对记录内容的认可。', risk_notes = '对照样本单份合同7处"有权直接扣除"式无程序扣款权：通知前置5个工作日+异议期5个工作日+争议部分冻结+违规扣减返还计息，四件套闭环；"拒签不视为认可"直接反制"拒签则按甲方记录为准"条款。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'deduction_procedure' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '送达条款', body_template = '双方确认：本合同首部及落款载明的地址为有效送达地址；未载明或载明不全的，以国家企业信用信息公示系统公示的住所地为准。有效送达地址适用于履约期间的催告、签证、计量、结算、扣款、解除等各类通知，以及争议解决阶段全部司法文书（含一审、二审、执行程序）的送达。一方地址变更的，应于变更后5日内书面通知对方；未依约通知的，原地址仍视为有效送达地址。书面通知可采用直接送交、邮政特快专递或双方确认的电子方式：直接送交以签收之日、快递以交邮后第3日、电子方式以发送成功之日视为送达；因收件方拒收、地址错误或迁址未告知导致邮件退回的，以退回之日视为送达。', risk_notes = '覆盖非诉与诉讼全阶段送达效力的条款是样本合同的普遍缺失项，可显著压缩争议阶段的公告送达周期；电子送达入列适配企业微信、邮件往来的留痕习惯。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'service_notice' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '争议解决', body_template = '因本合同订立及履行发生的争议，双方应先行友好协商，也可共同申请有关行业组织或人民调解委员会调解；自一方书面提出争议之日起30日内未能通过协商或调解解决的，任何一方均有权向本合同劳务作业所在地（即工程项目所在地）人民法院提起诉讼。争议处理期间，除争议事项本身外，双方仍应继续履行本合同无争议部分的义务；涉及农民工工资的款项应照常支付，不受争议影响。', risk_notes = '本节双向共用，管辖烘焙为劳务作业所在地：与建设工程纠纷地域管辖口径趋同、被认定无效的风险最小，并规避inbound场景被约定至对方注册地的单边管辖；如管理层要求严格我方所在地管辖，建议后续拆direction变体（inbound=乙方所在地/outbound=甲方所在地）。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'dispute' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '其他与生效', body_template = '本合同自双方盖章并由法定代表人或授权代理人签字之日起生效，生效不附加缴纳保证金、押金或其他任何先决条件。本合同附件（作业清单、安全管理协议、计量与签证单、损耗控制标准等）为本合同组成部分，与正文具有同等效力；附件与正文不一致的，以正文为准，但涉及农民工工资保障的内容，以更有利于保障工资支付的约定为准。未尽事宜由双方另行签订书面补充协议，补充协议与本合同具有同等效力。本合同一式肆份，甲乙双方各执贰份。合同各条款空白栏目应在用印前填写完整或划线注销；用印后仍留白的，视为双方对该事项未作约定，任何一方不得单方补填。', risk_notes = '"生效不附加保证金条件"对照样本生效条款与保证金条款内部矛盾的风险；"留白视为未约定+禁止单方补填"直击样本已盖章合同7处关键商业条款留白的真实事故，与系统定稿前必填校验形成双保险。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'misc_effective' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '落款', body_template = '（以下无正文，为本合同签署页）

甲方（盖章）：{{party_a}}
法定代表人/委托代理人（签字）：{{party_a_legal_person}}
统一社会信用代码：{{party_a_credit_code}}
开户银行：{{party_a_bank_name}}
账号：{{party_a_bank_account}}
签约日期：{{sign_date}}

乙方（盖章）：{{party_b}}
法定代表人/委托代理人（签字）：{{party_b_legal_person}}
统一社会信用代码：{{party_b_credit_code}}
开户银行：{{party_b_bank_name}}
账号：{{party_b_bank_account}}
签约日期：{{sign_date}}', risk_notes = '落款仅保留主体名称、授权签字人、统一社会信用代码与收付款账户要素，不采集任何个人证件号码；用印时印章应与首部主体名称完全一致并加盖骑缝章，账户信息与付款条款收款账户互为校验。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'labor_service' AND section_key = 'signature_block' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '首部与签约依据', body_template = '甲方（买方）：{{party_a}}，统一社会信用代码：{{party_a_credit_code}}。
乙方（卖方）：{{party_b}}，统一社会信用代码：{{party_b_credit_code}}。
根据《中华人民共和国民法典》及相关法律法规，双方本着平等自愿、诚实信用的原则，经协商一致，就{{project_name}}所需{{goods_name}}的购销事宜订立本合同，共同遵守。双方签认的《供货清单》、技术要求、封样记录等附件为本合同组成部分，与合同正文具有同等法律效力。', risk_notes = '材料族固定甲方=买方、乙方=卖方；inbound 我方卖方，outbound 我方买方。货物明细外置到签认附件（供货清单/封样）并赋合同效力，正文保持稳定，改型号不必改合同。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'parties_basis' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '标的、数量与质量标准', body_template = '货物名称：{{goods_name}}，具体规格型号、数量、单价以双方签认的《供货清单》为准。合同暂定总价人民币{{amount}}元（大写：{{amount_cn}}），单价为含税并含包装、运杂费的到场价，最终货款按双方签认的送货单据实结算。质量标准执行{{quality_standard}}及国家、行业现行强制性标准，并符合双方书面确认的技术要求；无上述标准的，以双方书面封样为准，不以卖方产品说明书或企业自定标准作为验收依据。卖方保证货物为全新合格产品，权属清晰、无权利负担，并随货提供出厂合格证、质量证明文件及检测报告，供买方进场报验使用。', risk_notes = 'outbound（我方采购）：质量标准外部化（国标/行标+书面技术要求+封样兜底），明确排除以卖方说明书自证（样本坑）；随货合格证与检测报告是工地进场报验刚需；总价烘焙为暂定总价+按签认送货单据实结算，覆盖建材数量浮动的常态。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'goods_spec' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '标的、数量与质量标准', body_template = '货物名称：{{goods_name}}，具体规格型号、数量、单价以双方签认的《供货清单》为准。合同暂定总价人民币{{amount}}元（大写：{{amount_cn}}），最终货款按双方签认的送货单或对账单据实结算。质量标准按{{quality_standard}}及产品出厂标准执行，卖方随货提供出厂合格证明；买方对特殊用途、更高标准或特定技术参数有要求的，应于下单前书面提出并经卖方书面确认，未经卖方书面确认的要求不构成卖方的质量义务。买方应保证其提供的规格型号、数量等要货信息准确完整，因要货信息错误产生的损失由买方承担。', risk_notes = 'inbound（我方销售）：质量承诺锚定出厂标准与书面确认的参数，特殊要求必须下单前书面固定，防事后加码；要货信息错误归责买方，防错单退货损失倒挂到我方。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'goods_spec' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '交货与风险转移', body_template = '交货时间：{{delivery_date}}，可分批交货的，以双方确认的要货计划为准；交货地点：{{delivery_place}}。除双方另有书面约定外，由卖方负责运输并承担至交货地点的运杂费，包装应符合货物性质及运输要求，包装物不另计价；双方约定买方自提的，买方在卖方指定提货点提货签认即视为交货。卖方应于发货前合理时间通知买方，便于买方安排卸货与验收。货物毁损、灭失的风险，自买方或其指定收货人在交货地点签收（含提货签认）时起由卖方转移至买方。卖方逾期交付的，每逾期一日按逾期部分货款的万分之五向买方支付违约金；违约金累计以合同暂定总价的10%为限。', risk_notes = '风险转移点显式锚定交货签收（样本缺失致物流扯皮）；补上样本没有的逾期交付违约金，费率烘焙为日万分之五、累计封顶合同价10%——outbound 我方买方有抓手，inbound 我方卖方敞口也有顶；送货到场为默认、自提为例外，一个条款覆盖两种履约形态。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'delivery' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '验收与质量异议', body_template = '货物到达交货地点后，买方应于7日内对货物外观、规格型号及数量进行验收并办理签收，验收不合格的有权拒收，卖方应限期补正或更换。对外观检验难以发现的隐蔽缺陷或内在质量问题，买方应于发现后30日内且最迟不超过质保期届满前以书面形式提出质量异议，办理签收不视为买方对该类缺陷的认可。质量异议经查证属实的，卖方应自收到异议通知后7日内无偿修理、更换或退货退款，并承担由此产生的运输、检测等费用；卖方逾期不处理的，买方有权采购替代货物，所增加的合理费用由卖方承担。', risk_notes = 'outbound：7日短窗只锁外观数量，隐蔽缺陷延伸至发现后30日且不晚于质保期届满，破样本『短异议期逾期视为合格』对买方的锁死；签收≠内在质量认可；卖方7日不处理触发替代采购追偿。句式刻意避开『自发现之日起…异议』的规则正则命中。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'acceptance' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '验收与质量异议', body_template = '货物到达交货地点或买方提货时，买方应当场核对品种、规格型号与数量；买方应于签收后7日内完成质量验收，未在该期限内提出书面异议的，视为货物数量、外观及质量均符合约定。买方提出质量异议的，应一并提供送货单、留样、影像资料等具体证据，不得仅以口头或笼统方式主张；双方对质量判定有分歧的，可共同委托有资质的第三方检验机构检验，检验费用由检验结论确定的责任方承担。异议经确认属实的，卖方负责修理、更换或补足数量；买方已使用、加工或安装的部分，视为该部分验收合格。', risk_notes = 'inbound：签收后7日短异议期+逾期视为符合，给我方卖货确定性；异议必须附证据，防空口翻价压款；第三方检验费跟责任方走；已使用部分视为合格，防边用边索赔。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'acceptance' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '货款支付', body_template = '货款按以下节点分期支付：（一）本合同签订生效后7日内，买方向卖方支付合同暂定总价30%的预付款；（二）货物到达交货地点并经买方验收合格后7日内，买方支付相应货款的60%，分批交货的按各批次货款分别计算，预付款按比例在各批次货款中冲抵；（三）其余10%货款作为尾款，于质保期届满且卖方处理完毕全部质量异议后15日内一次性付清。买方所有款项均支付至本合同落款载明的卖方账户；卖方变更收款账户的，应以加盖公章并经法定代表人签字的书面通知为准，否则买方有权暂缓支付，由此产生的损失由卖方承担。', risk_notes = 'outbound：30/60/10 分段支付破样本『付款发货』全款前置坑，90%货款在验收合格后才付足；10%尾款烘焙为质保期届满后15日付清，且刻意表述为『尾款』而非『质保金』——其性质是未到期货款，也避免规则层3%质保金上限误标；收款账户唯一化+变更双重签认，防冒名换卡诈骗。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'payment' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '货款支付', body_template = '付款方式默认为款到发货：买方付清相应批次货款后，卖方安排备货与发运。经卖方书面同意给予账期的，买方应于本合同签订生效后7日内预付合同暂定总价的50%，其余货款最迟于每批货物提货或发运前结清；未结清前卖方可暂缓发货，不视为逾期交付。买方逾期付款的，每逾期一日按未付金额的万分之五向卖方支付违约金；买方累计逾期超过30日的，卖方有权暂停后续备货及供货，并要求买方立即结清全部到期款项，相应交货期限顺延，卖方不因此承担违约责任。', risk_notes = 'inbound：先款后货为默认，赊销是例外且须我方书面同意（50%预付+提货/发运前结清）；逾期付款日万分之五，累计逾期30日触发停供+清欠+交期顺延三件套，且停供明确免责化，对冲对方以同时履行抗辩反咬。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'payment' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '所有权保留', body_template = '买方付清本合同项下全部货款前，已交付货物的所有权仍归卖方所有，买方仅可为{{project_name}}的施工需要合理领用，不得将货物转卖、抵押、出质或以其他方式处分。买方逾期付款，经卖方书面催告后10日内仍未付清的，卖方有权取回尚未使用的货物，买方应予配合，由此产生的运输、保管等费用由买方承担；货物已被消耗或已添附于工程无法取回的，不影响卖方继续追索货款、违约金及相关损失。卖方行使取回权，不影响其依法解除合同及主张其他违约救济。', risk_notes = 'inbound 专属：所有权保留+处分禁止+催告后取回权；针对建材易消耗、易添附的现实，明确取不回不灭失金钱债权追索，避免所有权保留在工程场景空转；源自样本卖方模版的合理条款，我方销售时直接采用。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'ownership' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '质量保证与责任', body_template = '卖方对货物提供{{warranty_months}}个月质量保证，自该批货物验收合格之日起算；国家强制性标准或卖方公开承诺的保修期限长于前述约定的，从其较长者。质保期内货物出现质量缺陷的，卖方应于接到买方通知后7日内无偿修理、更换或退货退款；因货物质量缺陷给买方造成损失的，卖方还应赔偿由此产生的合理直接损失，包括但不限于缺陷货物的拆卸、重新采购、重新安装、返工及检测费用，该赔偿责任不以缺陷货物自身价值为限。经更换或修复的货物或部件，其质保期自更换、修复完成之日起重新起算。', risk_notes = 'outbound：质量责任明确不封顶于货值——样本『赔偿限产品价值范围』是小额材料引发大额返工时买方最大坑，拆装/重购/返工/检测费点名列举为直接损失；更换件质保重新起算；法定或公开承诺的更长保修期自动吸收。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'quality_warranty' AND direction = 'outbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '质量保证与责任', body_template = '卖方对货物提供{{warranty_months}}个月质量保证，自该批货物验收合格之日起算。质保期内经双方确认属货物本身质量缺陷的，卖方负责修理或更换；卖方的赔偿责任以买方因此遭受的实际直接损失为限，不含停工损失、预期利润等间接损失，且累计赔偿总额不超过本合同实际结算总价。因买方保管不当、超范围或超负荷使用、自行改装、安装或施工工艺不当造成的损坏，不属于质保及赔偿范围。因人身损害产生的责任以及依法不得限制、免除的责任，不适用前述限额约定。', risk_notes = 'inbound：三重限缩——限实际直接损失、点名排除间接损失、累计上限合同结算总价；误用/改装/工艺不当明确出圈；保留人身损害与法定不可免责事项的例外，使限额条款自身经得起效力审查、不被整体击穿。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'quality_warranty' AND direction = 'inbound' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '发票与税务', body_template = '卖方应向买方开具税率为{{tax_rate}}%的增值税{{invoice_type}}发票，发票品名、规格、数量、金额均与实际交易一致，做到合同、货物、资金、发票相互对应；卖方不得以第三方名义开票或提供与实际交易不符的发票。卖方最迟应于收到每期款项后7日内开具并送达对应金额的发票；卖方未按约开票的，买方有权暂缓支付后续款项且不视为逾期付款，因此产生的税收损失由卖方承担。国家税率政策调整的，自调整生效之日起按新税率执行，含税价款相应调整，双方据实多退少补。', risk_notes = '票随款清（收款后7日内开票）两向皆宜：我方买方时未收票可暂缓后续付款且不算逾期，我方卖方时先款后货天然满足开票节奏；四流对应+禁第三方代开，防虚开发票连带；税率法定调整自动传导、据实多退少补，免签补充协议。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'invoice_tax' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '违约责任', body_template = '除本合同对逾期交付、逾期付款已单独约定违约金外，一方违反本合同约定给对方造成损失的，应向对方承担赔偿责任；违约金不足以弥补守约方实际损失的，守约方可就不足部分继续主张。一方迟延履行主要义务，经催告后在合理期限内仍未履行，或有其他根本违约行为致使合同目的不能实现的，守约方有权书面通知对方解除本合同，并要求违约方赔偿因此造成的损失。因不可抗力不能履行合同的，根据不可抗力的影响，部分或者全部免除责任；受影响一方应及时书面通知对方，并在合理期限内提供证明，双方应协商采取减损措施。', risk_notes = '分项违约金+损失补差，替代样本『任一方违约按总价20%』的一刀切互伤条款；解除权走催告+合理期限程序，防轻率解约；不可抗力通知+举证+减损并入本节，补齐材料族空白且不增加节数。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'breach' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '争议解决', body_template = '因本合同订立与履行所发生的一切争议，双方应首先友好协商解决；自一方书面提出争议之日起30日内协商不成的，任何一方均有权向原告住所地人民法院提起诉讼。协商及诉讼期间，本合同与争议无关的部分应继续履行，任何一方不得以存在争议为由拒付无争议的到期款项。败诉方应承担胜诉方为实现债权而支出的合理费用，包括但不限于诉讼费、保全费、保全保险费、公证费及律师费。', risk_notes = '管辖烘焙为原告住所地（原告就地）——样本中少见的对等写法，属民诉法允许的协议管辖范围，我方两个方向立场都不吃亏；无争议部分不停摆保供货连续；律师费等实现债权费用由败诉方承担，威慑恶意拖欠。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'dispute' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '其他与生效', body_template = '本合同自双方法定代表人或授权代表签字并加盖公章或合同专用章之日起生效。未尽事宜，双方可另行签订补充协议，补充协议与本合同具有同等法律效力；经双方签认的供货清单、技术要求、送货单、对账单等文件均为本合同组成部分。对本合同的任何变更均应采用书面形式并经双方签章确认。本合同一式肆份，甲乙双方各执贰份，具有同等法律效力；经双方确认的扫描件、传真件与原件具有同等效力。合同文本中的空白栏目应在签署前填写完整或划除；签署后的涂改未经双方签章确认的，对双方不发生效力。', risk_notes = '对症样本实证事故：已盖章合同7处关键条款留白、同份合同大写金额互相矛盾——空白栏目填写或划除、涂改须双方签章确认；签认单据并入合同，据实结算才有凭据链。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'misc_effective' AND direction = 'both' AND variant_key = 'default';

UPDATE contract_clause_template SET title = '落款', body_template = '甲方（买方，盖章）：{{party_a}}
统一社会信用代码：{{party_a_credit_code}}
法定代表人/委托代理人（签字）：
开户银行：{{party_a_bank_name}}
账号：{{party_a_bank_account}}
签约日期：{{sign_date}}

乙方（卖方，盖章）：{{party_b}}
统一社会信用代码：{{party_b_credit_code}}
法定代表人/委托代理人（签字）：
开户银行：{{party_b_bank_name}}
账号：{{party_b_bank_account}}
签约日期：{{sign_date}}', risk_notes = '落款账户与付款条款的『唯一收款账户』互为呼应；代理人姓名无对应占位符，固定为手签栏留待用印时填写，避免引入超纲占位符。', version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family = 'materials_sale' AND section_key = 'signature_block' AND direction = 'both' AND variant_key = 'default';
